function similarity(s1, s2) {
  let longer = s1.length > s2.length ? s1 : s2;
  let shorter = s1.length > s2.length ? s2 : s1;

  if (longer.length === 0) return 1.0;

  return (longer.length - editDistance(longer, shorter)) / parseFloat(longer.length);
}

function editDistance(s1, s2) {
  s1 = s1.toLowerCase();
  s2 = s2.toLowerCase();

  let costs = [];

  for (let i = 0; i <= s1.length; i++) {
    let lastValue = i;
    for (let j = 0; j <= s2.length; j++) {
      if (i === 0) {
        costs[j] = j;
      } else if (j > 0) {
        let newValue = costs[j - 1];
        if (s1.charAt(i - 1) !== s2.charAt(j - 1)) {
          newValue = Math.min(Math.min(newValue, lastValue), costs[j]) + 1;
        }
        costs[j - 1] = lastValue;
        lastValue = newValue;
      }
    }
    if (i > 0) costs[s2.length] = lastValue;
  }
  return costs[s2.length];
}

const beneficiaries = [
  "Vendor A",
  "Vendor B BEOGRAD",
  "Vendor C & PAYROLL Sp. z o.o.",
  "Vendor D",
  "LUX MED Sp. z o.o.",
  "Vendor E",
  "Vendor F",
  "Vendor G",
  "Employee D",
  "Vendor H Group, LLC",
  "Vendor I",
  "Vendor J",
  "Vendor K Gmbh (Wiesbaden)",
  "Vendor L",
  "Vendor M",
  "Vendor N Kamil Soczówka",
  "Vendor F",
  "Vendor O",
  "Vendor P No.1 doo Beograd",
  "DRUŠTVO ZA USLUGE U OBLASTI ZAŠTITE Vendor Q BEOGRAD (ČUKARICA)",
  "Društvo za reviziju i poslovno savetovanje Vendor R d.o.o. Beograd",
  "Vendor S s.r.o."
];

const input = $('Read data from attached forms').item.json.state.answers['16'].text;

let maxSimilarity = 0;
let bestMatch = '';
let allMatches = [];

for (const ben of beneficiaries) {
  const sim = similarity(input, ben);
  allMatches.push({
    beneficiary: ben,
    similarity: sim
  });
  if (sim > maxSimilarity) {
    maxSimilarity = sim;
    bestMatch = ben;
  }
}

return {
  input: input,
  match: maxSimilarity >= 0.5 ? bestMatch : 'empty',
  similarity: maxSimilarity,
  all_matches: allMatches
};

