/**
 * Code node expecting TWO inputs:
 *  - Input 1: main items (loop path)
 *  - Input 2: items from "Read data from attached forms"
 * Keeps all original fields from Input 1 and adds derived fields.
 */

// ---- helpers ----
const formCache = new WeakMap();

/**
 * Build and cache a Map { choiceId -> label } for (form, questionIndex)
 */
function getChoiceLabel(form, qIndex) {
  if (!form) return "";

  let perForm = formCache.get(form);
  if (!perForm) {
    perForm = {};
    formCache.set(form, perForm);
  }

  if (!perForm[qIndex]) {
    const choices = form?.design?.questions?.[qIndex]?.choices || [];
    perForm[qIndex] = new Map(choices.map(c => [c.id, c.label]));
  }

  const answerId = form?.state?.answers?.[qIndex]?.choices?.[0];
  if (!answerId) return "";
  return perForm[qIndex].get(answerId) || "";
}

// ---- inputs ----
const mainItems = $input.all(0);                 // from main branch
const formItems = $input.all(1);                 // from "Read data from attached forms"
const len = mainItems.length;

// Defensive: ensure same length; if not, pair as many as possible
const outLen = Math.min(len, formItems.length || len);

// ---- build output ----
const out = [];
for (let i = 0; i < outLen; i++) {
  const main = mainItems[i]?.json || {};
  const selfForm = main;                         // for "account" field (comes from self)
  const attachedForm = formItems[i]?.json || {}; // other fields come from attached form

  const result = {
    ...main, // keep ALL original fields
    account:   getChoiceLabel(selfForm, 4REDACTED),

    ptype:     getChoiceLabel(attachedForm, 51),
    curr:      getChoiceLabel(attachedForm, 29),
    payer:     getChoiceLabel(attachedForm, 14),
    allo:      getChoiceLabel(attachedForm, 23),
    alempl:    getChoiceLabel(attachedForm, 25),
    all_ent1:  getChoiceLabel(attachedForm, 31),
    all_pro:   getChoiceLabel(attachedForm, 32),
    prac_pool: getChoiceLabel(attachedForm, 71),
    all_pra:   getChoiceLabel(attachedForm, 33),
    paid_s:    getChoiceLabel(attachedForm, 52),
    operover:  getChoiceLabel(attachedForm, 46),
    budget:    getChoiceLabel(attachedForm, 47),
  };

  out.push({ json: result });
}

// If Input 2 had fewer items, pass through remaining main items unchanged
for (let i = outLen; i < len; i++) {
  out.push({ json: { ...mainItems[i].json } });
}

return out;
